INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Kann ich einen /48-Präfix in /64-Subnetze aufteilen?', 2, '[{"text": "Ja", "correct": true, "because": "16 Bits bleiben für Subnetze"}, {"text": "Nein", "correct": false, "because": "Aufteilung möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie viele /64-Subnetze passen in einen /56-Präfix?', 3, '[{"text": "256", "correct": true, "because": "2^(64-56) = 2^8"}, {"text": "64", "correct": false, "because": "Zu niedrig"}, {"text": "1024", "correct": false, "because": "Zu hoch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Bitanzahl leihe ich, um von /48 zu /64 aufzuteilen?', 4, '[{"text": "16", "correct": true, "because": "64 - 48 = 16"}, {"text": "8", "correct": false, "because": "Nicht ausreichend"}, {"text": "32", "correct": false, "because": "Zu viel"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Aufteilung von /48 zu /64 ergibt 65.536 Subnetze. b) Interface-ID bleibt 64 Bits.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "a) 2^16, b) Standard"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) auch korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) auch korrekt"}, {"text": "Beides falsch", "correct": false, "because": "Beide richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Aufteilung in /64-Subnetze?', 5, '[{"text": "Hostanzahl pro Subnetz", "correct": true, "because": "Fokus auf Subnetzanzahl"}, {"text": "Geliehene Bits", "correct": false, "because": "Bestimmen Subnetze"}, {"text": "Präfixlänge", "correct": false, "because": "Definiert Aufteilung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein /56-Präfix 256 /64-Subnetze ergibt?', 2, '[{"text": "Ja", "correct": true, "because": "2^8 = 256"}, {"text": "Nein", "correct": false, "because": "Formel passt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie viele /64-Subnetze entstehen aus einem /60-Präfix?', 3, '[{"text": "16", "correct": true, "because": "2^(64-60) = 2^4"}, {"text": "8", "correct": false, "because": "Zu niedrig"}, {"text": "32", "correct": false, "because": "Zu hoch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren beeinflussen die Aufteilung in /64-Subnetze?', 5, '[{"text": "Anzahl geliehener Bits", "correct": true, "because": "Bestimmt Subnetzanzahl"}, {"text": "Ursprünglicher Präfix", "correct": true, "because": "Basis der Teilung"}, {"text": "Bandbreite", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Von /48 zu /64 sind es 65.536 Subnetze. b) Interface-ID wird kleiner. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) falsch, bleibt 64 Bits"}, {"text": "Beides stimmt", "correct": false, "because": "b) ungenau"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Aufteilung in /64-Subnetze?', 4, '[{"text": "Präfixlänge", "correct": false, "because": "Definiert Subnetze"}, {"text": "Geliehene Bits", "correct": false, "because": "Bestimmen Anzahl"}, {"text": "Übertragungsrate", "correct": true, "because": "Unabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ergeben 6 geliehene Bits von /58 genau 64 /64-Subnetze?', 2, '[{"text": "Ja", "correct": true, "because": "2^6 = 64"}, {"text": "Nein", "correct": false, "because": "Formel stimmt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Werte ändern sich bei der Aufteilung von /48 zu /64?', 4, '[{"text": "Subnetzanzahl", "correct": true, "because": "Erhöht sich auf 2^16"}, {"text": "Netzwerkbits", "correct": true, "because": "48 zu 64"}, {"text": "Hostbits", "correct": false, "because": "Bleiben 64"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein /48-Präfix nur 1000 /64-Subnetze erlaubt. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "2^16 = 65.536"}, {"text": "Ja", "correct": false, "because": "Viel zu niedrig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Aufteilung in /64-Subnetze?', 3, '[{"text": "Subnetzanzahl", "correct": true, "because": "Hauptziel der Aufteilung"}, {"text": "Einzelne Adressen", "correct": false, "because": "Sekundär"}, {"text": "Kürzungsregeln", "correct": false, "because": "Darstellungssache"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) /56 zu /64 ergibt 256 Subnetze. b) Interface-ID ändert sich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) falsch, bleibt 64 Bits"}, {"text": "Beides stimmt", "correct": false, "because": "b) ungenau"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ergebnisse erwartest du bei der Aufteilung?', 5, '[{"text": "/48 zu /64 = 65.536 Subnetze", "correct": true, "because": "2^16"}, {"text": "/60 zu /64 = 16 Subnetze", "correct": true, "because": "2^4"}, {"text": "/56 zu /64 = 64 Subnetze", "correct": false, "because": "2^8 = 256"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Aufteilung in /64-Subnetze unwichtig?', 3, '[{"text": "Geliehene Bits", "correct": false, "because": "Bestimmen Anzahl"}, {"text": "Präfixlänge", "correct": false, "because": "Definiert Subnetze"}, {"text": "Farbcodierung", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind 10 geliehene Bits von /54 zu /64 möglich?', 2, '[{"text": "Ja", "correct": true, "because": "64 - 54 = 10"}, {"text": "Nein", "correct": false, "because": "Formel passt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob /48 zu /64 die Hostanzahl pro Subnetz ändert?', 3, '[{"text": "Nein", "correct": true, "because": "Hostbits bleiben 64"}, {"text": "Ja", "correct": false, "because": "Nur Subnetze erhöhen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Bitanzahl wähle ich, um von /56 zu /64 256 Subnetze zu erhalten?', 4, '[{"text": "8", "correct": true, "because": "2^8 = 256"}, {"text": "6", "correct": false, "because": "2^6 = 64"}, {"text": "10", "correct": false, "because": "2^10 = 1024"}]');
